:64,"problemId":"dcc1647c-fb7a-4a00-a81a-2c7b6da12cba","gid":null,"domain":"advanced_math","skill":"nonlinear_functions","difficulty":"hard","moduleKey":"math_m2","route":"higher"},{"section":"math","position":65,"problemId":"ee6d63bf-e28f-4247-9e1b-049d2fe6b547","gid":null,"domain":"advanced_math","skill":"nonlinear_equations_systems","difficulty":"hard","moduleKey":"math_m2","route":"higher"},{"section":"math","position":66,"problemId":"f5dec4a5-e85f-44fa-bbb3-2e105a59bf86","gid":null,"domain":"algebra","skill":"linear_equations_two_var","difficulty":"hard","moduleKey":"math_m2","route":"higher"}]}$satx$::jsonb;
  v_actor uuid := (select id from profiles where role = 'admin' order by created_at limit 1); v_tpl mock_exam_sets%rowtype; v_new uuid := gen_random_uuid(); v_cols text; it jsonb; v_pid uuid; v_p problems%rowtype; v_bad text;
begin
  if exists (select 1 from mock_exam_sets where name = v_set->>'name' and archived_at is null and status <> 'archived') then raise notice '% already exists (non-archived) - skipped', v_set->>'name'; return; end if;
  begin
    select * into v_tpl from mock_exam_sets where name = 'SAT Practice Test 13' and status = 'published' and archived_at is null limit 1;
    if v_tpl.id is null then raise exception 'template set (Test 13 published) missing'; end if;
    select string_agg(quote_ident(column_name), ', ' order by ordinal_position) into v_cols from information_schema.columns where table_schema = 'public' and table_name = 'mock_exam_sets' and is_generated = 'NEVER' and column_name not in ('id', 'set_group_id', 'version_no', 'name', 'status', 'created_by', 'created_at', 'published_at', 'published_by', 'archived_at', 'access_tier', 'readiness_status', 'readiness_report', 'readiness_checked_at');
    execute format('insert into mock_exam_sets (id, name, status, created_by, access_tier, %s) select $1, $2, ''draft'', $3, ''tutoring'', %s from mock_exam_sets where id = $4', v_cols, v_cols) using v_new, v_set->>'name', v_actor, v_tpl.id;
    for it in select * from jsonb_array_elements(v_set->'items') loop
      v_pid := coalesce((it->>'problemId')::uuid, (select problem_id from problem_versions where quality->'mockExamGeneration'->>'gid' = it->>'gid' limit 1));
      select * into v_p from problems where id = v_pid;
      if v_p.id is null or v_p.status <> 'confirmed' or v_p.archived_at is not null or v_p.published_version_id is null then raise exception 'item % % not usable (problem %)', it->>'section', it->>'position', v_pid; end if;
      insert into mock_exam_set_items (exam_set_id, section, position, problem_id, problem_version_id, sat_domain, skill_code, difficulty, module_key, route)
      values (v_new, it->>'section', (it->>'position')::int, v_pid, v_p.published_version_id, it->>'domain', it->>'skill', it->>'difficulty', (it->>'moduleKey')::mock_exam_module_key, nullif(it->>'route', '')::mock_exam_route);
    end loop;
    if not coalesce((public.mock_exam_validate_mst_set(v_new)->>'ready')::boolean, false) then raise exception 'new set: 4-module/rule validation failed %', public.mock_exam_validate_mst_set(v_new)::text; end if;
    select string_agg(x.problem_id::text || ':' || x.issue, ', ') into v_bad from (select * from public.mock_exam_set_item_issues(v_new) where issue is not null limit 5) x;
    if v_bad is not null then raise exception 'new set: item issues %', v_bad; end if;
    update mock_exam_sets set readiness_status = 'ready', readiness_report = public.mock_exam_validate_mst_set(v_new) || jsonb_build_object('shortfalls', '[]'::jsonb, 'checkedAt', now()), readiness_checked_at = now() where id = v_new;
    raise notice '% created as draft (%)', v_set->>'name', v_new;
  exception when others then raise notice '% SKIPPED: %', v_set->>'name', sqlerrm;
  end;
end
$ns$;
